// Packs the HTML pages into lib/pages.js so they are inside the serverless bundle and never served as public files.
// Run `npm run build:pages` after editing anything in /pages. The generated file is committed.
const fs = require('fs'), path = require('path');
const out = {};
for (const n of ['login', 'tool']) out[n] = fs.readFileSync(path.join(__dirname, '..', 'pages', n + '.html'), 'utf8');
fs.writeFileSync(path.join(__dirname, '..', 'lib', 'pages.js'), '// GENERATED by scripts/build-pages.js. Do not edit.\nmodule.exports = ' + JSON.stringify(out) + ';\n');
console.log('lib/pages.js written');
